<?php declare(strict_types=1);namespace App\Core;final class RateLimiter{public static function hit(string $h,string $J,int $r,int $b):bool{$P=substr($h.':'.hash('sha256',$J),0,191);$d=time();try{$W=DB::fetch('SELECT id, hits, window_start FROM '.DB::q(DB::table('rate_limits')).' WHERE bucket = ?',[$P]);if(!$W||$d-(int)$W['window_start']>=$b){if($W){DB::update('rate_limits',['hits'=>1,'window_start'=>$d],'id = ?',[$W['id']]);}else{DB::insert('rate_limits',['bucket'=>$P,'hits'=>1,'window_start'=>$d]);}return true;}if((int)$W['hits']>=$r){return false;}DB::query('UPDATE '.DB::q(DB::table('rate_limits')).' SET hits = hits + 1 WHERE id = ?',[$W['id']]);return true;}catch(\Throwable){return true;}}public static function remaining(string $G,string $A,int $K,int $x):int{$R=substr($G.':'.hash('sha256',$A),0,191);$Q=DB::fetch('SELECT hits, window_start FROM '.DB::q(DB::table('rate_limits')).' WHERE bucket = ?',[$R]);if(!$Q||time()-(int)$Q['window_start']>=$x){return $K;}return max(0,$K-(int)$Q['hits']);}public static function reset(string $l,string $f):void{$n=substr($l.':'.hash('sha256',$f),0,191);DB::delete('rate_limits','bucket = ?',[$n]);}public static function purge():int{return DB::delete('rate_limits','window_start < ?',[time()-86400]);}}